import * as React from "react";

export type StageDoorIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function StageDoorIcon({ size = 20, ...props }: StageDoorIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="3.5" width="12" height="17" rx="1" /><circle cx="14.5" cy="12" r="1" /><path d="M6 7.5h12" />
    </svg>
  );
}
